model:
package test.property_as_constraint {

class Angle {
  value:Int

  fun eq(other:Angle) : Bool
  {
    value = other.value
  }

  req value >= 0 && value <= 360
}

class Event {
  t1:Real
  t2:Real

  fun equal(e:Event) : Bool
  {
    (t1 = e.t1) && (t2 = e.t2)
  }

  fun meets(e:Event) : Bool
  {
    t2 = e.t1
  }
}

a1:Angle

a2:Angle

e1:Event

e2:Event

req a1.eq(a2)

req e1.meets(e2)


}
